/**
 * The small subset of JSON Schema AutoTrace needs to describe a required model response shape.
 * Providers that support structured output are given this schema so the model is constrained while
 * generating, but it never replaces runtime validation of what the model actually returned.
 */
export type JsonSchema = {
  type: "object" | "array" | "string";
  description?: string;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  items?: JsonSchema;
  enum?: string[];
  minItems?: number;
  maxItems?: number;
};
export type CandidateEvaluation = {
  result: SearchResult;
  score: number;
  signals: string[];
  exclusionReason: string | null;
};

// Normalize a URL for cross-query deduplication without changing the stored source URL.
export function normalizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    parsed.hash = "";
    parsed.hostname = parsed.hostname.toLowerCase();
    if (parsed.pathname.endsWith("/") && parsed.pathname.length > 1) {
      parsed.pathname = parsed.pathname.slice(0, -1);
    }
    for (const key of [...parsed.searchParams.keys()]) {
      const lower = key.toLowerCase();
      if (lower.startsWith("utm_") || TRACKING_PARAM_NAMES.has(lower)) {
        parsed.searchParams.delete(key);
      }
    }
    return parsed.toString();
  } catch {
    return url.trim().toLowerCase();
  }
}

// Keep the first occurrence of each destination URL across all queries.
export function deduplicateByUrl(results: SearchResult[]): SearchResult[] {
  const seen = new Set<string>();
  const unique: SearchResult[] = [];
  for (const result of results) {
    const key = normalizeUrl(result.url);
    if (!key || seen.has(key)) {
      continue;
    }
    seen.add(key);
    unique.push(result);
  }
  return unique;
